/** osu!lazer's mod icon: a rounded hexagon in the mod type's colour with the mod's glyph on it. */
function modIcon(id, size = 36) {
  const m = MOD_BY_ID.get(id), c = m ? m.color : '#888';
  const el = h('span.mod-icon', { style: { '--mod': c, width: size + 'px', height: Math.round(size * 0.72) + 'px' }, title: m ? m.name : id });
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', '0 0 50 36');
  svg.innerHTML = `<path d="M10 2h30a4 4 0 013.4 1.9l5.2 9a10 10 0 010 10.2l-5.2 9A4 4 0 0140 34H10a4 4 0 01-3.4-1.9l-5.2-9a10 10 0 010-10.2l5.2-9A4 4 0 0110 2z" class="mi-bg"/>`
    + `<g transform="translate(15 8) scale(.83)" class="mi-g">${(MOD_GLYPHS[id] || '').replace(/class="fillme"/g, 'class="mi-fill"')}</g>`
    + (MOD_GLYPHS[id] ? '' : `<text x="25" y="23" text-anchor="middle" class="mi-t">${id}</text>`);
  el.append(svg);
  return el;
}
const MOD_GROUPS = [['reduction', 'Difficulty Reduction'], ['increase', 'Difficulty Increase'], ['conversion', 'Conversion'], ['automation', 'Automation'], ['fun', 'Fun']];
const MOD_CONFIG_DEFAULTS = { acc: 0.9, od: 8, hp: 8, rate: 1.2, cover: 0.5, percy: 150, flSize: 1, muCount: 100, muInverse: 0, muMetronome: 1, coDir: 0 };

const ModSystem = {
  normalize(list) { return MODS.filter(m => list.includes(m.id)).map(m => m.id); },
  toggle(list, id) {
    const m = MOD_BY_ID.get(id);
    if (!m) return list;
    // (Cinema is Auto with nothing drawn over the background: it brings Auto with it, and goes with it)
    const tie = r => r.includes('CN') && !r.includes('AT') ? this.normalize([...r, 'AT']) : r;
    if (list.includes(id)) return list.filter(x => x !== id && !(id === 'AT' && x === 'CN'));
    return tie(this.normalize([...list.filter(x => !m.incompatible.includes(x) && !(MOD_BY_ID.get(x)?.incompatible || []).includes(id)), id]));
  },
  config(cfg) { return { ...MOD_CONFIG_DEFAULTS, ...(cfg || (typeof Settings !== 'undefined' ? Settings.get('mods.config') : null) || {}) }; },
  multiplier(list, cfg) {
    let m = list.reduce((a, id) => a * (MOD_BY_ID.get(id)?.mult ?? 1), 1);
    if (list.includes('RT') && this.config(cfg).rate < 1) m *= 0.5;
    return m;
  },
  rate(list, cfg) {
    if (list.includes('RT')) return clamp(Math.round(this.config(cfg).rate * 20) / 20, 0.5, 2);
    for (const id of list) { const r = MOD_BY_ID.get(id)?.rate; if (r) return r; }
    return 1;
  },
  pitchShift(list) { return list.some(id => MOD_BY_ID.get(id)?.pitch); },
  /** Wind Up / Wind Down: the playback rate at the first note and at the last ([from, to]), or null. */
  adaptive(list) { return list.some(id => MOD_BY_ID.get(id)?.adaptive); },
  ramp(list) { for (const id of list) { const r = MOD_BY_ID.get(id)?.ramp; if (r) return r; } return null; },
  label(list) { return list.length ? list.join('') : 'NM'; },
  /** The column count a key mod (1K–10K) asks for, or 0. */
  keyMod(list) { for (const id of list || []) { const m = /^(\d+)K$/.exec(id); if (m && MOD_BY_ID.has(id)) return +m[1]; } return 0; },
  isRanked(list) { return !list.some(id => MOD_BY_ID.get(id)?.unranked); },
  /** Column permutation for Mirror / Random. */
  columnMap(list, keys, seed) {
    const map = Array.from({ length: keys }, (_, i) => i);
    if (list.includes('MR')) map.reverse();
    if (list.includes('RD')) {
      const rnd = mulberry32(seed);
      for (let i = keys - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [map[i], map[j]] = [map[j], map[i]]; }
    }
    return map;
  },
  /** Short human description of configured values (shown on badges / results). */
  describe(id, cfg) {
    const c = this.config(cfg);
    if (id === 'AC') return `${Math.round(c.acc * 100)}%`;
    if (id === 'RT') return `${this.rate(['RT'], cfg)}×`;
    if (id === 'DA') return `OD${c.od} HP${c.hp}`;
    if (id === 'HD' || id === 'FI') return `${Math.round(c.cover * 100)}%`;
    if (id === 'CO') return `${Math.round(c.cover * 100)}% ${c.coDir ? '↑' : '↓'}`;
    if (id === 'PC') return `${c.percy}ms`;
    if (id === 'FL') return `${c.flSize}×`;
    if (id === 'MU') return `${c.muCount}x`;
    return '';
  },
  badge(id, small = false, cfg = null) {
    const m = MOD_BY_ID.get(id);
    const d = cfg ? this.describe(id, cfg) : '';
    return h(`span.mod-badge${small ? '.small' : ''}`, { style: { '--mod': m ? m.color : '#888' }, title: m ? `${m.name}${d ? ' ' + d : ''}` : id },
      modIcon(id, small ? 24 : 30), h('span.mb-t', id));
  },
};

/* ===== 09-gameplay.js ===== */
/* JudgementSystem / ScoreSystem / HealthSystem / GameplayEngine.
 * Pure, deterministic logic: given notes and a sequence of (column, down/up, songTime) inputs it
 * always produces the same result. Live play and replay playback share this code path exactly.
 *
 * Judging rules (`rules`):
 *   2 — osu!lazer's osu!mania rules, checked line by line against the osu!lazer source (ppy/osu:
 *       DrawableNote, DrawableHoldNote(+Head/Tail/Body), ManiaHitWindows, OrderedHitPolicy,
 *       ManiaHealthProcessor, ManiaModHardRock/Easy/Perfect). Used for every new play.
 *   1 — the rules plays were judged with before; replays recorded then keep them, so they re-score exactly. */

const J = { MARV: 0, PERF: 1, GREAT: 2, GOOD: 3, BAD: 4, MISS: 5 };
const JUDGEMENTS = [
  { id: '300g', name: 'Marvelous', short: 'MAX', score: 320, color: '#ffe066' },
  { id: '300', name: 'Perfect', short: '300', score: 300, color: '#ffc233' },
  { id: '200', name: 'Great', short: '200', score: 200, color: '#38d97a' },
  { id: '100', name: 'Good', short: '100', score: 100, color: '#3c9dff' },
  { id: '50', name: 'Bad', short: '50', score: 50, color: '#b07cf0' },
  { id: '0', name: 'Miss', short: 'MISS', score: 0, color: '#ff4a5c' },
];
const TAIL_LENIENCE = 1.5;
/** The judging rules new plays use (replays store the rules they were recorded with). */
const RULES = 2;

/** Timing windows in real milliseconds, [MAX, 300, 200, 100, 50, miss] (osu!mania table from OD).
 *  osu!mania's Easy / Hard Rock scale the windows themselves (×1.4 / ÷1.4) and leave OD alone; rules 1
 *  changed OD instead. Difficulty Adjust sets OD directly. */
function timingWindows({ od = 5, mods = [], mode = 'od', customOD = 8, customMs = '', odOverride = null, rules = RULES } = {}) {
  if (mode === 'ms') {
    const p = String(customMs).split(/[,\s]+/).map(Number).filter(n => isFinite(n) && n > 0);
    if (p.length === 6) return p.slice().sort((a, b) => a - b);
  }
  const base = mode === 'custom' ? customOD : od;
  const override = mods.includes('DA') ? odOverride : null;
  if (rules < 2) return OsuMath.hitWindows(OsuMath.odAfterMods(base, mods, override));
  const m = mods.includes('HR') ? 1 / 1.4 : mods.includes('EZ') ? 1.4 : 1;
  return OsuMath.hitWindows(override != null ? override : base).map(w => w * m);
}

/** osu!lazer standardised scoring (ManiaScoreProcessor): each judgement adds its base score (a MAX counts 300)
 *  times log₄(combo after it), between 0.5 and log₄(400); the combo part is worth 150,000 and accuracy
 *  (MAX = 305) 850,000 × acc^(2 + 2·acc). */
const STD_COMBO_BASE = [300, 300, 200, 100, 50, 0];
const STD_COMBO_CAP = Math.log(400) / Math.log(4);
const stdComboFactor = c => Math.min(Math.max(0.5, Math.log(c) / Math.log(4)), STD_COMBO_CAP);

/** ScoreV1 osu!mania scoring (1,000,000 max) with bonus, osu! accuracy and max combo — and, alongside it,
 *  osu!lazer's standardised score (`scoreStd`). */
class ScoreSystem {
  constructor(totalJudgements, { mods = [], accuracyMode = 'v2' } = {}) {
    this.total = Math.max(1, totalJudgements);
    this.mult = ModSystem.multiplier(mods);
    this.accMode = accuracyMode;
    this.counts = [0, 0, 0, 0, 0, 0];
    this.judged = 0; this.combo = 0; this.maxCombo = 0;
    this.bonus = 100; this.rawScore = 0;
    this.comboBreaks = 0;
    this.comboPortion = 0; this.maxComboPortion = 0;
    for (let k = 1; k <= this.total; k++) this.maxComboPortion += 300 * stdComboFactor(k);
  }
  add(j) {
    this.counts[j]++; this.judged++;
    const unit = 1e6 / 2 / this.total;
    this.bonus = clamp(this.bonus + SCORE_V1.bonusChange[j], 0, 100);
    this.rawScore += (unit * SCORE_V1.value[j] / 320 + unit * SCORE_V1.bonusValue[j] * Math.sqrt(this.bonus) / 320) * this.mult;
    if (j === J.MISS) this.breakCombo();
    else { this.combo++; if (this.combo > this.maxCombo) this.maxCombo = this.combo; }
    this.comboPortion += STD_COMBO_BASE[j] * stdComboFactor(this.combo);
  }
  breakCombo() { if (this.combo > 0) this.comboBreaks++; this.combo = 0; }
  get accuracy() { return this.accMode === 'v1' ? OsuMath.accuracyV1(this.counts) : OsuMath.accuracy(this.counts); }
  get score() { return Math.round(this.rawScore); }
  get scoreStd() {
    const acc = OsuMath.accuracy(this.counts);
    const combo = this.maxComboPortion > 0 ? this.comboPortion / this.maxComboPortion : 1;
    return Math.round((150000 * combo + 850000 * Math.pow(acc, 2 + 2 * acc) * (this.judged / this.total)) * this.mult);
  }
  grade(failed = false, mods = []) { return ScoreSystem.gradeFor(this.accuracy, failed, mods, this.counts); }
  static gradeFor(acc, failed, mods = [], counts = null) {
    return OsuMath.grade(acc, counts, failed, mods.includes('HD') || mods.includes('FI') || mods.includes('FL')); // (lazer's silver ranks: Hidden, Fade In, Flashlight)
  }
}

/** osu!mania health (legacy draining processor calibration + per-judgement changes). */
class HealthSystem {
  constructor({ hp = 5, mods = [], noFail = false, notes = [], breaks = [], hpOverride = null, accChallenge = null, rules = RULES, hpMult = null } = {}) {
    this.value = 1;
    this.lazer = rules >= 2;
    const hpMod = OsuMath.hpAfterMods(hp, mods, mods.includes('DA') ? hpOverride : null);
    // osu!lazer uses the drain rate after mods for everything; rules 1 used the unmodified one for the changes
    this.rawHp = this.lazer ? hpMod : (mods.includes('DA') && hpOverride != null ? hpOverride : hp);
    this.mult = hpMult ?? computeHpMultiplier(notes, hpMod, breaks, this.rawHp); // (a fixed one for previews: working it out simulates the whole map)
    this.noFail = noFail || mods.includes('NF') || mods.includes('AT');
    this.suddenDeath = mods.includes('SD');
    this.perfect = mods.includes('PF');
    this.perfectSS = mods.includes('PSS');
    this.accChallenge = mods.includes('AC') ? (accChallenge ?? 0.9) : null;
    this.failed = false; this.failTime = null;
    this.min = 1;
    this.timeline = [];
  }
  apply(j, t, hold = false, accuracy = 1) {
    if ((this.suddenDeath && j === J.MISS) || (this.perfect && j >= J.GREAT) || (this.perfectSS && j !== J.MARV)) {
      this.value = 0; this.fail(t);
    } else {
      this.value = clamp(this.value + healthIncrease(j, this.rawHp, hold, this.mult), 0, 1);
    }
    if (this.accChallenge != null && accuracy < this.accChallenge) this.fail(t);
    if (this.value < this.min) this.min = this.value;
    if (this.value <= 0) this.fail(t);
    this.timeline.push([Math.round(t), Math.round(this.value * 1000) / 1000]);
  }
  /** A hold released too early (its body breaks combo): Sudden Death fails, and in osu!lazer so do Perfect / SS. */
  earlyRelease(t) { if (this.suddenDeath || (this.lazer && (this.perfect || this.perfectSS))) this.fail(t); }
  fail(t) { if (this.noFail || this.failed) return; this.failed = true; this.failTime = t; }
}

/** Note states */
const NS = { PENDING: 0, HOLDING: 1, DONE: 2, MISSED: 3, DROPPED: 4 };

class GameplayEngine {
  /**
   * @param {object} o
   * @param {Array} o.notes  mania notes (already column-mapped / converted for mods)
   * @param {number} o.keys
   * @param {number[]} o.windows real-time windows [marv..miss] ms
   * @param {number} o.rate playback rate (map-time windows = real * rate)
   * @param {number} o.rules judging rules (see top of file)
   */
  constructor({ notes, keys, windows, rate = 1, mods = [], hp = 5, accuracyMode = 'v2', noFail = false, breaks = [], modConfig = {}, rules = RULES, hpMult = null }) {
    this.keys = keys; this.rate = rate; this.mods = mods;
    this.rules = rules; this.lazer = rules >= 2;
    // No Release (osu!lazer ManiaModNoRelease): a hold still held when its end arrives is a MAX (a 50 if it broke)
    this.noRelease = this.lazer && mods.includes('NR');
    // Windows in song time. In osu!mania they scale with the playback rate, so the real-time window never changes
    // (IManiaRateAdjustmentMod); osu!lazer floors each one and adds half a millisecond (ManiaHitWindows).
    this.W = this.lazer ? windows.map(w => Math.floor(w * rate + 1e-9) + 0.5) : windows.map(w => w * rate);
    this.TW = this.W.map(w => w * TAIL_LENIENCE);
    this.notes = notes.map((n, i) => ({ ...n, i, state: NS.PENDING, headJ: -1, tailJ: -1, capped: false, bodyBroken: false, holdStart: 0, hitTime: 0 }));
    this.columns = Array.from({ length: keys }, () => []);
    for (const n of this.notes) this.columns[n.col].push(n);
    this.ptr = new Array(keys).fill(0);
    this.held = new Array(keys).fill(false);
    this.holding = new Array(keys).fill(null);
    const totalJ = this.notes.reduce((a, n) => a + (n.isLN ? 2 : 1), 0);
    this.totalJudgements = totalJ;
    this.score = new ScoreSystem(totalJ, { mods, accuracyMode });
    this.health = new HealthSystem({ hp, mods, noFail, notes: this.notes, breaks, hpOverride: modConfig.hp ?? null, accChallenge: modConfig.acc ?? null, rules, hpMult });
    this.hitErrors = [];            // {t, err (real ms), j, tail}
    this.judgementLog = [];         // {t, j, col}
    this.lastJudgement = null;
    this.remaining = totalJ;
    this.listeners = [];
    this.inputCount = 0;
    this.pressCounts = new Array(keys).fill(0);
    this.lastTime = -Infinity;
  }
  onEvent(fn) { this.listeners.push(fn); }
  _emit(e) { for (const fn of this.listeners) fn(e); }

  _judge(n, j, t, err, tail) {
    this.score.add(j);
    // osu!lazer: misses on either end of a hold (head or tail) cost half a note's health; rules 1: only the tail
    this.health.apply(j, t, this.lazer ? n.isLN : tail, this.score.accuracy);
    this.remaining--;
    const e = { type: 'judgement', col: n.col, j, t, err, tail, note: n };
    this.lastJudgement = e;
    this.judgementLog.push({ t, j, col: n.col });
    if (err !== null && j !== J.MISS) this.hitErrors.push({ t, err: err / this.rate, j, tail });
    this._emit(e);
  }
  _windowFor(absErr, W) {
    for (let j = 0; j < 5; j++) if (absErr <= W[j]) return j;
    return J.MISS;
  }
  /** The column's current note (the first one not fully judged), or undefined. */
  _cur(c) {
    const col = this.columns[c];
    let p = this.ptr[c];
    while (p < col.length && (col[p].state === NS.DONE || col[p].state === NS.MISSED)) p++;
    this.ptr[c] = p;
    return col[p];
  }

  /** Process misses / auto-resolutions up to song time t. */
  advance(t) {
    if (t < this.lastTime) t = this.lastTime;
    this.lastTime = t;
    if (this.lazer) this._advanceLazer(t); else this._advanceLegacy(t);
  }

  /** osu!lazer: a note can't be hit any more once it's later than the 50 window (HitWindows.CanBeHit), and a hold's
   *  tail once it's later than 1.5× that. Resolved in time order across all columns. */
  _expiry(n) {
    if (n.state === NS.PENDING) return n.time + this.W[J.BAD];
    if (this.noRelease && n.state === NS.HOLDING) return n.end;
    return n.end + this.TW[J.BAD]; // HOLDING (held too long) or DROPPED (let go / head missed)
  }
  _advanceLazer(t) {
    for (;;) {
      let best = -1, bestT = Infinity;
      for (let c = 0; c < this.keys; c++) {
        const n = this._cur(c);
        if (!n) continue;
        const x = this._expiry(n);
        if (x < bestT) { bestT = x; best = c; }
      }
      if (best < 0 || !(t > bestT)) return;
      const n = this.columns[best][this.ptr[best]];
      if (n.state === NS.PENDING) {
        n.headJ = J.MISS;
        if (n.isLN) { n.state = NS.DROPPED; n.capped = true; } else { n.state = NS.MISSED; this.ptr[best]++; }
        this._judge(n, J.MISS, bestT, null, false);
      } else if (this.noRelease && n.state === NS.HOLDING) {
        // held through to the end: no release timing needed
        if (this.holding[best] === n) this.holding[best] = null;
        const j = n.capped ? J.BAD : J.MARV;
        n.tailJ = j; n.state = NS.DONE; this.ptr[best]++;
        this._judge(n, j, bestT, null, true);
      } else {
        if (this.holding[best] === n) this.holding[best] = null;
        n.tailJ = J.MISS; n.state = NS.MISSED; this.ptr[best]++;
        this._judge(n, J.MISS, bestT, null, true);
      }
    }
  }
  _advanceLegacy(t) {
    for (let c = 0; c < this.keys; c++) {
      const col = this.columns[c];
      let p = this.ptr[c];
      while (p < col.length) {
        const n = col[p];
        if (n.state === NS.PENDING) {
          if (t - n.time > this.W[J.MISS]) {
            this._judge(n, J.MISS, n.time + this.W[J.MISS], null, false);
            if (n.isLN) { n.state = NS.DROPPED; n.headJ = J.MISS; continue; }
            n.state = NS.MISSED; n.headJ = J.MISS; p++; continue;
          }
          break;
        } else if (n.state === NS.HOLDING) {
          if (t - n.end > this.TW[J.MISS]) {
            // held past the release window without letting go: the tail is missed
            n.tailJ = J.MISS; n.state = NS.MISSED;
            this.holding[c] = null;
            this._judge(n, J.MISS, n.end + this.TW[J.MISS], null, true);
            p++; continue;
          }
          break;
        } else if (n.state === NS.DROPPED) {
          if (t > n.end) {
            n.tailJ = J.MISS; n.state = NS.MISSED;
            this._judge(n, J.MISS, n.end, null, true);
            p++; continue;
          }
          break;
        } else { p++; }
      }
      this.ptr[c] = p;
    }
  }

  /** osu!lazer note lock (OrderedHitPolicy): hitting a note misses the earlier, still unjudged one in its column. */
  _forceMiss(n, c, t) {
    if (n.state === NS.PENDING) { n.headJ = J.MISS; this._judge(n, J.MISS, t, null, false); }
    if (n.isLN) {
      if (this.holding[c] === n) this.holding[c] = null;
      n.tailJ = J.MISS; this._judge(n, J.MISS, t, null, true);
    }
    n.state = NS.MISSED; this.ptr[c]++; // n is always the column's current note here
  }

  /** Key press/release at song time t (map ms). */
  input(col, down, t) {
    if (col < 0 || col >= this.keys) return;
    this.advance(t);
    this.inputCount++;
    if (down) {
      if (this.held[col]) return;
      this.held[col] = true;
      this.pressCounts[col]++;
      if (this.lazer) { this._pressLazer(col, t); return; }
      const colNotes = this.columns[col];
      const n = colNotes[this.ptr[col]];
      this._emit({ type: 'press', col, t, note: n || null });
      if (!n) return;
      if (n.state === NS.PENDING) {
        const err = t - n.time;
        if (err < -this.W[J.MISS]) return; // too early: nothing happens
        const j = this._windowFor(Math.abs(err), this.W);
        n.headJ = j; n.hitTime = t;
        if (n.isLN) {
          if (j === J.MISS) { n.state = NS.DROPPED; this._judge(n, j, t, err, false); }
          else { n.state = NS.HOLDING; n.holdStart = t; this.holding[col] = n; this._judge(n, j, t, err, false); }
        } else {
          n.state = j === J.MISS ? NS.MISSED : NS.DONE;
          this._judge(n, j, t, err, false);
          this.ptr[col]++;
        }
      } else if (n.state === NS.DROPPED && !n.released && t >= n.time - this.W[J.BAD] && t <= n.end) {
        // grab a long note whose head was missed: tail result is capped at Bad (one let go mid-hold can't be held again)
        n.state = NS.HOLDING; n.capped = true; this.holding[col] = n;
        this._emit({ type: 'regrab', col, t, note: n });
      }
    } else {
      if (!this.held[col]) return;
      this.held[col] = false;
      this._emit({ type: 'release', col, t });
      const n = this.holding[col];
      if (!n) return;
      this.holding[col] = null;
      const err = t - n.end;
      if (err < -this.TW[J.MISS]) {
        // released too early: the hold's body breaks combo, and it can't be held again — its tail is missed once
        // its window passes (pressing the column again does nothing to it)
        n.state = NS.DROPPED; n.capped = true; n.released = true;
        const broke = !this.lazer || !n.bodyBroken;
        n.bodyBroken = true;
        if (broke) { this.score.breakCombo(); this.health.earlyRelease(t); }
        this._emit({ type: 'earlyRelease', col, t, note: n, broke });
        return;
      }
      let j = this._windowFor(Math.abs(err), this.TW);
      // a broken hold's tail is capped at 50 (a miss stays a miss in osu!lazer)
      if (n.capped) j = this.lazer ? Math.max(j, J.BAD) : J.BAD;
      n.tailJ = j; n.state = this.lazer && j === J.MISS ? NS.MISSED : NS.DONE;
      this._judge(n, j, t, err, true);
      this.ptr[col]++;
    }
  }
  /** osu!lazer press: DrawableNote / DrawableHoldNote.OnPressed with the ordered hit policy. */
  _pressLazer(col, t) {
    let n = this._cur(col);
    this._emit({ type: 'press', col, t, note: n || null });
    while (n) {
      const next = this.columns[col][this.ptr[col] + 1];
      const hittable = !next || t < next.time; // a note can't be hit once the next one in its column has started
      if (n.state === NS.PENDING) {
        if (!hittable) { this._forceMiss(n, col, t); n = this._cur(col); continue; }
        const err = t - n.time;
        if (err < -this.W[J.MISS]) return; // too early: nothing happens
        const j = this._windowFor(Math.abs(err), this.W);
        n.headJ = j; n.hitTime = t;
        if (n.isLN) {
          // the hold begins even when the head is an early miss; its tail can then be at most a 50
          n.state = NS.HOLDING; n.holdStart = t; n.capped = j === J.MISS; this.holding[col] = n;
          this._judge(n, j, t, err, false);
        } else {
          n.state = j === J.MISS ? NS.MISSED : NS.DONE; this.ptr[col]++;
          this._judge(n, j, t, err, false);
        }
        return;
      }
      if (n.state === NS.DROPPED) {
        // hold it again: from the head's miss window until 50-window after the end (never in the tail's extra lenience)
        if (!n.released && hittable && t - n.time >= -this.W[J.MISS] && !(t > n.end && t - n.end > this.W[J.BAD])) {
          n.state = NS.HOLDING; n.capped = true; this.holding[col] = n;
          this._emit({ type: 'regrab', col, t, note: n });
          return;
        }
        if (!hittable) { this._forceMiss(n, col, t); n = this._cur(col); continue; }
      }
      return;
    }
  }

  get finished() { return this.remaining <= 0; }
  get endTime() { return this.notes.length ? Math.max(...this.notes.slice(-this.keys * 4).map(n => n.end)) : 0; }

  /** Reset notes in [from, to] (practice looping). */
  resetRange(from, to) {
    for (let c = 0; c < this.keys; c++) {
      const col = this.columns[c];
      let first = -1;
      for (let i = 0; i < col.length; i++) {
        const n = col[i];
        if (n.time >= from - 1 && n.time <= to) {
          if (n.state !== NS.PENDING) this.remaining += n.isLN ? 2 : 1;
          n.state = NS.PENDING; n.headJ = -1; n.tailJ = -1; n.capped = false; n.bodyBroken = false;
          if (first < 0) first = i;
        }
      }
      if (first >= 0) this.ptr[c] = Math.min(this.ptr[c], first);
      this.held[c] = false; this.holding[c] = null;
    }
    this.lastTime = from - 1;
  }

  summary() {
    const errs = this.hitErrors.filter(e => !e.tail).map(e => e.err);
    const mean = errs.length ? errs.reduce((a, b) => a + b, 0) / errs.length : 0;
    const sd = errs.length > 1 ? Math.sqrt(errs.reduce((a, b) => a + (b - mean) ** 2, 0) / (errs.length - 1)) : 0;
    return {
      score: this.score.score, scoreStd: this.score.scoreStd, accuracy: this.score.accuracy, maxCombo: this.score.maxCombo, combo: this.score.combo,
      counts: [...this.score.counts], comboBreaks: this.score.comboBreaks,
      meanError: mean, unstableRate: sd * 10,
      early: errs.filter(e => e < 0).length, late: errs.filter(e => e > 0).length,
      hitErrors: this.hitErrors.map(e => [Math.round(e.t), Math.round(e.err * 10) / 10, e.j, e.tail ? 1 : 0]),
      totalJudgements: this.totalJudgements,
    };
  }
}

/** Prepare notes for a play: apply column map (MR/RD) and NLN. */
function prepareNotes(notes, keys, mods, seed, { red = null } = {}) {
  const map = ModSystem.columnMap(mods, keys, seed);
  const nln = mods.includes('NLN');
  const out = notes.map(n => ({ ...n, col: map[n.col], isLN: nln ? false : n.isLN, end: nln ? n.time : n.end }));
  return mods.includes('IN') ? invertNotes(out, keys, red) : out;
}

/** osu!lazer's Invert (ManiaModInvert): in each column, every note (or hold head) becomes a hold lasting until
 *  the next one starts, shortened by a quarter beat (at most by half) so there's always a gap to press again.
 *  The last note of each column has nothing to hold to and is dropped. red: uninherited timing points. */
function invertNotes(notes, keys, red) {
  const beatAt = t => {
    if (!red || !red.length) return 500;
    let bl = red[0].beatLength;
    for (const r of red) { if (r.time <= t) bl = r.beatLength; else break; }
    return bl;
  };
  const out = [];
  for (let c = 0; c < keys; c++) {
    const col = notes.filter(n => n.col === c).sort((a, b) => a.time - b.time);
    for (let i = 0; i < col.length - 1; i++) {
      const n = col[i], next = col[i + 1];
      let dur = next.time - n.time;
      dur = Math.max(dur / 2, dur - beatAt(next.time) / 4);
      if (!(dur > 0)) continue;
      out.push({ ...n, isLN: true, end: n.time + dur });
    }
  }
  return out.sort((a, b) => a.time - b.time || a.col - b.col);
}

/** Auto: generate a perfect input stream. Returns flat events [t, col, down(1/0)] sorted. */
function generateAutoInputs(notes, keys) {
  const byCol = Array.from({ length: keys }, () => []);
  for (const n of notes) byCol[n.col].push(n);
  const ev = [];
  for (const col of byCol) {
    for (let i = 0; i < col.length; i++) {
      const n = col[i], next = col[i + 1];
      let up = n.isLN ? n.end : n.time + 45;
      if (next && up >= next.time) up = n.isLN ? n.end : (n.time + next.time) / 2;
      ev.push([n.time, n.col, 1], [up, n.col, 0]);
    }
  }
  ev.sort((a, b) => a[0] - b[0] || a[2] - b[2]);
  return ev;
}

/* ===== 09a-osu-math.js ===== */
/* OsuMath — osu!mania-accurate formulas.
 *
 * Ported from Web-Osu-Mania by Danny Duong (MIT License, Copyright (c) 2024 Danny Duong,
 * https://github.com/hectickiwi/Web-Osu-Mania), which in turn follows the official osu! sources:
 *   - hit windows:  https://osu.ppy.sh/wiki/en/Gameplay/Judgement/osu%21mania#scorev2
 *   - ScoreV1:      https://osu.ppy.sh/wiki/en/Gameplay/Score/ScoreV1/osu%21mania
 *   - accuracy:     https://osu.ppy.sh/wiki/en/Gameplay/Accuracy#osu!mania
 *   - health:       osu.Game/Rulesets/Scoring/LegacyDrainingHealthProcessor.cs, ManiaHealthProcessor.cs
 *   - star rating:  osu.Game.Rulesets.Mania/Difficulty/ManiaDifficultyCalculator.cs (+ Strain.cs, evaluators)
 *   - pp:           osu.Game.Rulesets.Mania/Difficulty/ManiaPerformanceCalculator.cs
 *
 * The MIT permission notice for the ported portions:
 *   Permission is hereby granted, free of charge, to any person obtaining a copy of this software and
 *   associated documentation files (the "Software"), to deal in the Software without restriction,
 *   including without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense,
 *   and/or sell copies of the Software, and to permit persons to whom the Software is furnished to do so,
 *   subject to the following conditions: The above copyright notice and this permission notice shall be
 *   included in all copies or substantial portions of the Software.
 *   THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND.
 */

const OsuMath = {
  /** OD after EZ / HR (osu! applies these to the difficulty value, not to the windows). */
  odAfterMods(od, mods = [], override = null) {
    if (mods.includes('EZ')) return od / 2;
    if (mods.includes('HR')) return Math.min(od * 1.4, 10);
    if (override != null) return override;
    return od;
  },
  hpAfterMods(hp, mods = [], override = null) {
    if (mods.includes('EZ')) return hp / 2;
    if (mods.includes('HR')) return Math.min(hp * 1.4, 10);
    if (override != null) return override;
    return hp;
  },

  /** osu!mania ScoreV2-table hit windows (ms, real time): [MAX, 300, 200, 100, 50, miss]. */
  hitWindows(od) {
    return [
      od <= 5 ? 22.4 - 0.6 * od : 24.9 - 1.1 * od,
      64 - 3 * od, 97 - 3 * od, 127 - 3 * od, 151 - 3 * od, 188 - 3 * od,
    ];
  },

  /** Displayed accuracy (MAX weighted 305). counts: [MAX,300,200,100,50,miss] */
  accuracy(c) {
    const n = c[0] + c[1] + c[2] + c[3] + c[4] + c[5];
    if (!n) return 1;
    return (305 * c[0] + 300 * c[1] + 200 * c[2] + 100 * c[3] + 50 * c[4]) / (305 * n);
  },
  /** Classic accuracy (MAX == 300). */
  accuracyV1(c) {
    const n = c[0] + c[1] + c[2] + c[3] + c[4] + c[5];
    if (!n) return 1;
    return (300 * (c[0] + c[1]) + 200 * c[2] + 100 * c[3] + 50 * c[4]) / (300 * n);
  },
  /** Accuracy used by pp (MAX weighted 320). */
  ppAccuracy(c) {
    const n = c[0] + c[1] + c[2] + c[3] + c[4] + c[5];
    if (!n) return 1;
    return (320 * c[0] + 300 * c[1] + 200 * c[2] + 100 * c[3] + 50 * c[4]) / (320 * n);
  },

  /** Performance points (ManiaPerformanceCalculator). starRating must already include rate mods. */
  pp(starRating, counts, mods = []) {
    const totalHits = counts.reduce((a, b) => a + b, 0);
    if (!totalHits) return 0;
    const acc = this.ppAccuracy(counts);
    let value = 8 * Math.pow(Math.max(starRating - 0.15, 0.05), 2.2) * Math.max(0, 5 * acc - 4) * (1 + 0.1 * Math.min(1, totalHits / 1500));
    if (mods.includes('NF')) value *= 0.75;
    if (mods.includes('EZ')) value *= 0.5;
    return value;
  },
  /** Profile total pp, as osu!'s servers work it out for lazer (UserTotalPerformanceProcessor): the best score on each
   *  ranked beatmap, highest first, the top 1000 of them weighted 0.95^i — plus the bonus for how many there are,
   *  416.6667 × (1 − 0.995^n) (n up to 1000). */
  totalPp(ppList) {
    const sorted = ppList.filter(p => p > 0).sort((a, b) => b - a).slice(0, 1000);
    let weighted = 0, w = 1;
    for (const p of sorted) { weighted += p * w; w *= 0.95; }
    const bonus = this.bonusPp(sorted.length);
    return { total: weighted + bonus, weighted, bonus };
  },
  bonusPp(n) { return n > 0 ? 416.6667 * (1 - Math.pow(0.995, Math.min(n, 1000))) : 0; },

  /** Letter grade (osu!lazer ManiaScoreProcessor.RankFromScore): SS = only MAX / 300 hits; then 95 / 90 / 80 / 70%
   *  and up for S / A / B / C. */
  grade(acc, counts, failed = false, hidden = false) {
    if (failed) return 'F';
    if (counts && counts[2] + counts[3] + counts[4] + counts[5] === 0) return hidden ? 'XH' : 'SS';
    if (acc >= 0.95) return hidden ? 'SH' : 'S';
    if (acc >= 0.9) return 'A';
    if (acc >= 0.8) return 'B';
    if (acc >= 0.7) return 'C';
    return 'D';
  },

  // https://github.com/ppy/osu/blob/master/osu.Game/Beatmaps/IBeatmapDifficultyInfo.cs
  difficultyRange(d, min, mid, max) {
    if (d > 5) return mid + (max - mid) * (d - 5) / 5;
    if (d < 5) return mid + (mid - min) * (d - 5) / 5;
    return mid;
  },
};

/** ScoreV1 (osu!mania) with the hit-bonus mechanic. Values indexed like J (MAX..miss). */
const SCORE_V1 = {
  value: [320, 300, 200, 100, 50, 0],
  bonusValue: [32, 32, 16, 8, 4, 0],
  bonusChange: [2, 1, -8, -24, -44, -100],
};

/** Legacy mania health: calibrates hpMultiplierNormal by simulating a perfect play, then applies
 *  per-judgement increases (hold-tail misses cost half). */
function computeHpMultiplier(notes, hp, breaks = [], rawHp = hp) {
  const lowestHpEver = OsuMath.difficultyRange(hp, 0.975, 0.8, 0.3);
  const lowestHpEnd = OsuMath.difficultyRange(hp, 0.99, 0.9, 0.4);
  const hpRecoveryAvailable = OsuMath.difficultyRange(hp, 0.04, 0.02, 0);
  let hpMultiplierNormal = 1;
  if (!notes.length) return 1;
  const heads = notes.slice().sort((a, b) => a.time - b.time);
  const drainStart = heads[0].time;
  const increaseFor = (j, hold) => healthIncrease(j, rawHp, hold, hpMultiplierNormal);
  let testDrop = 0.00025;
  for (let guard = 0; guard < 4000; guard++) {
    let currentHp = 1, currentHpUncapped = 1, lastTime = drainStart, currentBreak = 0, fail = false, count = 0;
    const reduce = amt => { currentHpUncapped = Math.max(0, currentHpUncapped - amt); currentHp = Math.max(0, currentHp - amt); };
    const increase = hold => { const a = increaseFor(J.MARV, hold); currentHpUncapped += a; currentHp = Math.max(0, Math.min(1, currentHp + a)); };
    for (const h of heads) {
      count++;
      while (currentBreak < breaks.length && breaks[currentBreak].end <= h.time) { lastTime = h.time; currentBreak++; }
      reduce(testDrop * (h.time - lastTime));
      lastTime = h.end;
      if (currentHp <= lowestHpEver) { fail = true; testDrop *= 0.96; break; }
      const reduction = testDrop * (h.end - h.time);
      const overkill = Math.max(0, reduction - currentHp);
      reduce(reduction);
      if (h.isLN) { increase(true); increase(true); }
      if (overkill > 0 && currentHp - overkill <= lowestHpEver) { fail = true; testDrop *= 0.96; break; }
      if (!h.isLN) increase(false);
    }
    if (!fail && currentHp < lowestHpEnd) { fail = true; testDrop *= 0.94; hpMultiplierNormal *= 1.01; }
    const recovery = (currentHpUncapped - 1) / Math.max(1, count);
    if (!fail && recovery < hpRecoveryAvailable) { fail = true; testDrop *= 0.96; hpMultiplierNormal *= 1.01; }
    if (!fail && !isFinite(hpMultiplierNormal)) return 1;
    if (!fail) return hpMultiplierNormal;
  }
  return hpMultiplierNormal;
}
function healthIncrease(j, hp, hold, mult = 1) {
  switch (j) {
    case J.MISS: return hold ? -(hp + 1) * 0.00375 : -(hp + 1) * 0.0075;
    case J.BAD: return -(hp + 1) * 0.0016;
    case J.GOOD: return 0;
    case J.GREAT: return mult * (0.004 - hp * 0.0004);
    case J.PERF: return mult * (0.005 - hp * 0.0005);
    default: return mult * (0.0055 - hp * 0.0005);
  }
}

/** Star rating: port of osu!lazer's ManiaDifficultyCalculator (Strain skill). */
const ManiaStarRating = {
  DIFFICULTY_MULTIPLIER: 0.018, INDIVIDUAL_DECAY_BASE: 0.125, OVERALL_DECAY_BASE: 0.3,
  DECAY_WEIGHT: 0.9, SECTION_LENGTH: 400, RELEASE_THRESHOLD: 30,

  calculate(notes, keys, rate = 1) {
    if (notes.length < 2) return 0;
    const hos = notes.map(n => ({ startTime: n.time / rate, endTime: (n.isLN ? n.end : n.time) / rate, column: n.col }))
      .sort((a, b) => Math.round(a.startTime) - Math.round(b.startTime));
    const objs = this._diffObjects(hos, keys);
    return this._strain(objs, keys) * this.DIFFICULTY_MULTIPLIER;
  },
  _diffObjects(hos, keys) {
    const objects = [], perCol = Array.from({ length: keys }, () => []);
    for (let i = 1; i < hos.length; i++) {
      const cur = hos[i], last = hos[i - 1];
      const col = perCol[cur.column] || (perCol[cur.column] = []);
      const prevInCol = col[col.length - 1] || null;
      const prevs = new Array(keys).fill(null);
      if (objects.length) {
        const p = objects[objects.length - 1];
        for (let j = 0; j < keys; j++) prevs[j] = p.prevs[j];
        prevs[p.column] = p;
      }
      const o = {
        index: objects.length, startTime: cur.startTime, endTime: cur.endTime, deltaTime: cur.startTime - last.startTime,
        column: cur.column, columnStrainTime: prevInCol ? cur.startTime - prevInCol.startTime : cur.startTime, prevs,
      };
      objects.push(o); col.push(o);
    }
    return objects;
  },
  _strain(objects, keys) {
    const decay = (v, dt, base) => v * Math.pow(base, dt / 1000);
    const bigger = (a, b, d) => a - b > d;
    const logistic = (x, mid, mul, max = 1) => max / (1 + Math.exp(mul * (mid - x)));
    const indiv = new Array(keys).fill(0);
    let highestIndiv = 0, overall = 1, currentStrain = 0, sectionPeak = 0, sectionEnd = 0;
    const peaks = [];
    for (const cur of objects) {
      if (cur.index === 0) sectionEnd = Math.ceil(cur.startTime / this.SECTION_LENGTH) * this.SECTION_LENGTH;
      while (cur.startTime > sectionEnd) {
        peaks.push(sectionPeak);
        const prev = cur.index > 0 ? objects[cur.index - 1] : null;
        const prevStart = prev ? prev.startTime : cur.startTime;
        sectionPeak = decay(highestIndiv, sectionEnd - prevStart, this.INDIVIDUAL_DECAY_BASE) + decay(overall, sectionEnd - prevStart, this.OVERALL_DECAY_BASE);
        sectionEnd += this.SECTION_LENGTH;
      }
      currentStrain *= Math.pow(1, cur.deltaTime / 1000);
      // individual strain
      let holdFactor = 1;
      for (const p of cur.prevs) {
        if (p && bigger(p.endTime, cur.endTime, 1) && bigger(cur.startTime, p.startTime, 1)) { holdFactor = 1.25; break; }
      }
      indiv[cur.column] = decay(indiv[cur.column], cur.columnStrainTime, this.INDIVIDUAL_DECAY_BASE) + 2 * holdFactor;
      highestIndiv = cur.deltaTime <= 1 ? Math.max(highestIndiv, indiv[cur.column]) : indiv[cur.column];
      // overall strain
      let overlapping = false, closestEnd = Math.abs(cur.endTime - cur.startTime), hf = 1, holdAdd = 0;
      for (const p of cur.prevs) {
        if (!p) continue;
        overlapping = overlapping || (bigger(p.endTime, cur.startTime, 1) && bigger(cur.endTime, p.endTime, 1) && bigger(cur.startTime, p.startTime, 1));
        if (bigger(p.endTime, cur.endTime, 1) && bigger(cur.startTime, p.startTime, 1)) hf = 1.25;
        closestEnd = Math.min(closestEnd, Math.abs(cur.endTime - p.endTime));
      }
      if (overlapping) holdAdd = logistic(closestEnd, this.RELEASE_THRESHOLD, 0.27);
      overall = decay(overall, cur.deltaTime, this.OVERALL_DECAY_BASE) + (1 + holdAdd) * hf;
      currentStrain += highestIndiv + overall - currentStrain;
      sectionPeak = Math.max(currentStrain, sectionPeak);
    }
    peaks.push(sectionPeak);
    let diff = 0, w = 1;
    for (const p of peaks.filter(x => x > 0).sort((a, b) => b - a)) { diff += p * w; w *= this.DECAY_WEIGHT; }
    return diff;
  },
};

/* ===== 09c-verify.js ===== */
/* Score verification: the game server's own judge of a play. It never takes a player's word for a score — given the
 * beatmap file (checked against its hash by the server) and the play's recorded key presses, it plays them through
 * the same judging engine the game uses, under the standard rules (the beatmap's own OD, the default accuracy), and
 * works out the score, accuracy, combo, grade, star rating and pp itself. The same file runs in the game and, bundled
 * by build.mjs, on the server (worker/verify-bundle.js). */

/** Mods that change the notes themselves (No Long Notes, Invert): their star rating is the changed notes'. */
const convertsNotes = mods => mods.includes('NLN') || mods.includes('IN');

const VERIFY = {
  MAX_EVENTS: 600000,      // numbers in a replay (t, col, down per key event)
  MIN_HOLD: 5,             // ms a key is held at the least (a press and release closer than that isn't a finger)
  MAX_RATE: 2, MIN_RATE: 0.5,
  BOT_UR: 15, BOT_NOTES: 100, // an unstable rate below this over at least this many hits is a script, not a person
};

/** Judge a play. `osuText`: the beatmap file; `play`: { mods, modConfig, seed, events }. Returns the result, or
 *  { error } when the play can't count (not a pass, unranked mods, impossible input). `noFail`: a multiplayer play,
 *  which plays on after health runs out (as the game does there) — it comes back `failed`, an F worth 0pp. */
function verifyPlay(osuText, play, { noFail = false } = {}) {
  const fail = error => ({ error });
  if (typeof osuText !== 'string' || !play || typeof play !== 'object') return fail('bad play');
  let bm;
  try { bm = BeatmapParser.parse(osuText); } catch (e) { return fail('the beatmap could not be read'); }
  // mods: only real ones, and only ranked ones (no Auto, no Autopilot-like helpers)
  const mods = ModSystem.normalize(Array.isArray(play.mods) ? play.mods.map(String) : []);
  // (a key mod converts an osu! map to that many columns)
  const keyMod = bm.mode === 0 ? ModSystem.keyMod(mods) : 0;
  let keys, notes;
  try { keys = BeatmapParser.keyCount(bm, keyMod); notes = BeatmapParser.toManiaNotes(bm, keyMod); } catch (e) { return fail('not a playable beatmap'); }
  if (!(keys >= 1 && keys <= 18)) return fail('not an osu!mania beatmap');
  if (!notes.length) return fail('the beatmap has no notes');
  if (!ModSystem.isRanked(mods)) return fail('unranked mods');
  const cfg = play.modConfig && typeof play.modConfig === 'object' ? play.modConfig : {};
  const modConfig = {};
  for (const k of ['rate', 'od', 'hp', 'acc', 'cover', 'percy']) if (Number.isFinite(Number(cfg[k]))) modConfig[k] = Number(cfg[k]);
  const rate = ModSystem.rate(mods, modConfig);
  if (!(rate >= VERIFY.MIN_RATE && rate <= VERIFY.MAX_RATE)) return fail('speed out of range');
  const seed = Number.isFinite(Number(play.seed)) ? Number(play.seed) | 0 : 0;
  // input: [t, col, down] triples, in time order, each column alternating press / release
  const ev = play.events;
  if (!Array.isArray(ev) || ev.length % 3 || ev.length > VERIFY.MAX_EVENTS) return fail('bad input');
  const down = new Array(keys).fill(-1);
  let last = -Infinity;
  for (let i = 0; i < ev.length; i += 3) {
    const t = ev[i], col = ev[i + 1], d = ev[i + 2];
    if (!Number.isFinite(t) || !Number.isInteger(col) || col < 0 || col >= keys || (d !== 0 && d !== 1)) return fail('bad input');
    if (t < last - 0.001) return fail('input out of order');
    last = t;
    if (d === 1) { if (down[col] >= 0) return fail('impossible input'); down[col] = t; }
    else { if (down[col] < 0) return fail('impossible input'); if ((t - down[col]) / rate < VERIFY.MIN_HOLD) return fail('impossible input'); down[col] = -1; }
  }
  // the play itself, judged as the game judges it — standard windows for the beatmap and mods
  const red = BeatmapParser.timing(bm).red;
  const playNotes = prepareNotes(notes, keys, mods, seed, { red });
  const windows = timingWindows({ od: bm.od, mods, odOverride: modConfig.od, rules: RULES });
  const engine = new GameplayEngine({ notes: playNotes, keys, windows, rate, mods, hp: bm.hp, accuracyMode: 'v2', noFail,
    breaks: mods.includes('IN') ? [] : bm.events.breaks, modConfig, rules: RULES });
  for (let i = 0; i < ev.length; i += 3) {
    engine.advance(ev[i]);
    engine.input(ev[i + 1], ev[i + 2] === 1, ev[i]);
  }
  const end = Math.max(...playNotes.map(n => n.end)) + 10000;
  engine.advance(end);
  // (multiplayer: health running out marks the play failed, though it played on)
  const failed = noFail ? engine.health.min <= 0 : engine.health.failed && !mods.includes('NF');
  if (failed && !noFail) return fail('the play failed');
  const sum = engine.summary();
  // a script pressing every key at exactly the right moment: no person hits a hundred notes that evenly
  const judged = sum.counts.slice(0, 5).reduce((a, b) => a + b, 0);
  if (judged >= VERIFY.BOT_NOTES && sum.unstableRate < VERIFY.BOT_UR) return fail('inhuman timing');
  const starNotes = convertsNotes(mods) ? playNotes : notes;
  const stars = DifficultyCalculator.calculate(starNotes, keys, rate);
  const pp = failed ? 0 : OsuMath.pp(stars, sum.counts, mods);
  const grade = ScoreSystem.gradeFor(sum.accuracy, failed, mods, sum.counts);
  return {
    score: Math.round(sum.scoreStd != null ? sum.scoreStd : sum.score), accuracy: sum.accuracy, maxCombo: sum.maxCombo, counts: sum.counts,
    grade, stars, pp, mods, keys, rate, unstableRate: sum.unstableRate, failed,
    beatmapSetId: Number(bm.metadata && bm.metadata.BeatmapSetID) || -1,
    beatmapId: Number(bm.metadata && bm.metadata.BeatmapID) || -1, title: (bm.metadata && bm.metadata.Title) || '', artist: (bm.metadata && bm.metadata.Artist) || '', version: (bm.metadata && bm.metadata.Version) || '',
  };
}

export { verifyPlay };
